package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"

	"syscli/internal/platform"
)

func main() {
	asJSON := flag.Bool("json", false, "print output as JSON")
	flag.Parse()

	info, err := platform.Query()
	if err != nil {
		fmt.Fprintln(os.Stderr, "syscli:", err)
		os.Exit(1)
	}

	if *asJSON {
		enc := json.NewEncoder(os.Stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(info); err != nil {
			fmt.Fprintln(os.Stderr, "syscli:", err)
			os.Exit(1)
		}
		return
	}

	fmt.Printf("OS:      %s\n", info.OS)
	fmt.Printf("Release: %s\n", info.Release)
	fmt.Printf("Machine: %s\n", info.Machine)
	if info.Extra != "" {
		fmt.Printf("Extra:   %s\n", info.Extra)
	}
}

// Package platform gathers OS and kernel details using low-level system calls
// that are not exposed by the Go standard library.
//
// The public API is defined here and implemented once per operating system in
// files with matching build constraints (platform_linux.go, platform_darwin.go,
// platform_windows.go). Consumers only ever import this package and call Query.
package platform

// Info describes the running operating system and kernel.
type Info struct {
	OS      string `json:"os"`
	Release string `json:"release"`
	Machine string `json:"machine"`
	Extra   string `json:"extra,omitempty"`
}

