//go:build linux

package platform

import "golang.org/x/sys/unix"

// Query uses unix.Uname, which wraps the uname(2) syscall. The standard
// library does not expose the full utsname struct, so this is done via
// golang.org/x/sys/unix.
func Query() (Info, error) {
	var u unix.Utsname
	if err := unix.Uname(&u); err != nil {
		return Info{}, err
	}
	return Info{
		OS:      unix.ByteSliceToString(u.Sysname[:]),
		Release: unix.ByteSliceToString(u.Release[:]),
		Machine: unix.ByteSliceToString(u.Machine[:]),
		Extra:   unix.ByteSliceToString(u.Version[:]),
	}, nil
}

//go:build darwin

package platform

import "golang.org/x/sys/unix"

// Query reads the kernel identity through the sysctl(3) interface, which gives
// richer values than uname(2) on Darwin. These calls are not part of the
// standard library.
func Query() (Info, error) {
	osType, err := unix.Sysctl("kern.ostype")
	if err != nil {
		return Info{}, err
	}
	release, err := unix.Sysctl("kern.osrelease")
	if err != nil {
		return Info{}, err
	}
	machine, err := unix.Sysctl("hw.machine")
	if err != nil {
		return Info{}, err
	}
	version, err := unix.Sysctl("kern.version")
	if err != nil {
		return Info{}, err
	}
	return Info{
		OS:      osType,
		Release: release,
		Machine: machine,
		Extra:   version,
	}, nil
}

//go:build windows

package platform

import (
	"runtime"
	"syscall"
	"unsafe"

	"golang.org/x/sys/windows"
)

// rtlOSVersionInfo mirrors RTL_OSVERSIONINFOW from the Windows DDK.
type rtlOSVersionInfo struct {
	OSVersionInfoSize uint32
	MajorVersion      uint32
	MinorVersion      uint32
	BuildNumber       uint32
	PlatformID        uint32
	CSDVersion        [128]uint16
}

var (
	ntdll              = windows.NewLazySystemDLL("ntdll.dll")
	procRtlGetVersion  = ntdll.NewProc("RtlGetVersion")
)

// Query calls ntdll!RtlGetVersion. Unlike GetVersionEx, this is not subject to
// application-compatibility manifest shimming, and the window(x32/64) ABI
// details are not surfaced by the standard library.
func Query() (Info, error) {
	var vi rtlOSVersionInfo
	vi.OSVersionInfoSize = uint32(unsafe.Sizeof(vi))
	ret, _, _ := procRtlGetVersion.Call(uintptr(unsafe.Pointer(&vi)))
	if ret != 0 {
		return Info{}, syscall.Errno(ret)
	}
	return Info{
		OS:      "windows",
		Release: itoa(vi.MajorVersion) + "." + itoa(vi.MinorVersion) + "." + itoa(vi.BuildNumber),
		Machine: runtime.GOARCH,
		Extra:   csdVersion(vi.CSDVersion),
	}, nil
}

func itoa(v uint32) string {
	if v == 0 {
		return "0"
	}
	var buf [10]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	return string(buf[i:])
}

func csdVersion(b [128]uint16) string {
	n := 0
	for n < len(b) && b[n] != 0 {
		n++
	}
	return syscall.UTF16ToString(b[:n])
}

//go:build !linux && !darwin && !windows

package platform

import "errors"

// ErrUnsupported is returned by Query on platforms without an implementation.
var ErrUnsupported = errors.New("platform: unsupported operating system")

// Query is a stub for operating systems that this tool does not support yet.
func Query() (Info, error) {
	return Info{}, ErrUnsupported
}

//go:build windows

package platform

import (
	"runtime"
	"strconv"
	"unsafe"

	"golang.org/x/sys/windows"
)

// rtlOSVersionInfo mirrors RTL_OSVERSIONINFOW from the Windows DDK.
type rtlOSVersionInfo struct {
	OSVersionInfoSize uint32
	MajorVersion      uint32
	MinorVersion      uint32
	BuildNumber       uint32
	PlatformID        uint32
	CSDVersion        [128]uint16
}

var (
	ntdll             = windows.NewLazySystemDLL("ntdll.dll")
	procRtlGetVersion = ntdll.NewProc("RtlGetVersion")
)

// Query calls ntdll!RtlGetVersion. Unlike GetVersionEx, it is not subject to
// application-compatibility manifest shimming, and the resulting version
// information is not surfaced by the standard library.
func Query() (Info, error) {
	var vi rtlOSVersionInfo
	vi.OSVersionInfoSize = uint32(unsafe.Sizeof(vi))
	ret, _, _ := procRtlGetVersion.Call(uintptr(unsafe.Pointer(&vi)))
	if ret != 0 {
		return Info{}, windows.Errno(ret)
	}
	release := strconv.Itoa(int(vi.MajorVersion)) + "." +
		strconv.Itoa(int(vi.MinorVersion)) + "." +
		strconv.Itoa(int(vi.BuildNumber))
	return Info{
		OS:      "windows",
		Release: release,
		Machine: runtime.GOARCH,
		Extra:   windows.UTF16ToString(vi.CSDVersion[:]),
	}, nil
}

